'use strict';
const $ = (s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=v=>typeof v==='string'?v: v==null?'':JSON.stringify(v);
const num=v=>v===''||v==null?null:Number.isFinite(Number(v))?Number(v):null;
const nf=new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2});
const fmt=v=>num(v)==null?'—':nf.format(Number(v));
const amount=v=>num(v)==null?'待询价':`${fmt(v)} 万`;
const uniq=a=>[...new Set(a)];
const safeUrl=v=>/^(https?:\/\/|data:image\/(png|jpeg|webp|gif);base64,|(?:\.\/)?(?:assets|avatars|images)\/)/i.test(String(v||''))?v:'';
const external=(url,label)=>safeUrl(url)&&/^https?:/.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
const titleById=['','成为网红，拯救世界','和朋友胡闹的日常','现实里早就想这么干','职业切换与角色魅力','写实二次元与真实地标','武学与武器战斗','载具与独特行动方式','双城烟火气','混厄与意外奇遇','鲜活的城市交互','趣味道具 · 跳舞枪','特色动作与步态','电影化剧情体验'];
const budgetDefaults=[['头部达人合作',1500],['创意性事件',300],['直播单',600],['游戏性内容',700],['攻略单',100],['线下试玩',500],['COS单',300],['杭州IN77春节传播',50],['重庆李子坝传播',50],['上影元春节电影院活动传播',50]];
const ICONS={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-14 4h3m3 0h3"/>',pair:'<rect x="2" y="4" width="13" height="14" rx="2"/><path d="M16 8h4a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-8v-2M6 11h6m-3-3v6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m3 11v-3a6 6 0 0 0-3-5"/>',bulb:'<path d="M9 18h6m-5 3h4M9 15c0-2-4-3-4-7a7 7 0 0 1 14 0c0 4-4 5-4 7Z"/>',graph:'<circle cx="12" cy="4" r="3"/><circle cx="4" cy="19" r="3"/><circle cx="20" cy="19" r="3"/><path d="m10 7-4 9m8-9 4 9M7 19h10"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V4a1 1 0 0 1 1-1h14M16 12h5v4h-5Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',file:'<path d="M14 2H5v20h14V7Zm0 0v6h5M8 12h8m-8 4h6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 17V5m-5 5 5-5 5 5M4 17v4h16v-4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L20 5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',edit:'<path d="m14 4 6 6M4 20l5-1L21 7l-4-4L5 15Zm0 0 1-5"/>',link:'<path d="m9 15 6-6M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.grid}</svg>`;
let state=null, research={profiles:[],edges:[]}, avatarManifest=[], seed=null, saving=false, lastSaved='', blocked=false;
const viewParam=new URLSearchParams(location.search).get('view');
const requestedView=window.KOLPersistence?.readonly && viewParam==='sources'?'pool':viewParam;
let ui={view:['overview','kols','ideas','factory','pool','calendar','relations','budgets','selling','sources'].includes(requestedView)?requestedView:'kols',q:'',category:'',content:'',sell:'',selection:'',status:'',sort:'selected',page:1,ideaQ:'',ideaType:'',ideaSell:'',ideaBudget:'',ideaStatus:'active',focus:'',edge:'',graphMode:'all'};
let modal=null, modalBeforeFocus=null, toastTimer, listeners=[], lastSaveProblem='';
const storageKey='ananta-kol-lab-v1';
const getKol=id=>state.kols.find(k=>String(k.id)===String(id));
const selectedKols=()=>state.kols.filter(k=>k.selected);
const activeIdeas=()=>state.ideas.filter(i=>!i.archived);
const budgetIdeas=()=>activeIdeas().filter(i=>i.inBudget);
const sellName=id=>(state?.sellingPoints||[]).find(p=>Number(p.id)===Number(id))?.title||titleById[id]||'未分类';
const shortSell=id=>titleById[id]||sellName(id);
function pill(text,tone=''){return `<span class="pill ${tone}">${esc(text)}</span>`;}
const avatarLoadFailures=new Set(),avatarLoaded=new Set();
function avatarUrlFor(k){const value=safeUrl(k?.avatar||k?.avatarUrl||'');return value&&!avatarLoadFailures.has(value)?value:'';}
function avatarStats(){const matched=state.kols.filter(k=>avatarUrlFor(k));return {matched:matched.length,verified:matched.filter(k=>k.avatarAssetVerified===true||avatarLoaded.has(avatarUrlFor(k))).length,failed:state.kols.filter(k=>avatarLoadFailures.has(safeUrl(k.avatar||k.avatarUrl||''))).length};}
function updateAvatarCounters(){if(!state)return;const stats=avatarStats();for(const el of $$('[data-avatar-count]'))el.textContent=fmt(stats.verified);for(const el of $$('[data-avatar-summary]'))el.textContent=`${stats.matched}位已有头像路径 · ${stats.failed}位加载失败`;}
function avatarSourceNote(k){if(k?.avatarUserOwned||k?.avatarOrigin==='user')return '人工设置头像';if(k?.historicalAvatar)return `历史头像${k.sourceSnapshotDate?' · 来源日期 '+k.sourceSnapshotDate:''}`;if(k?.currentAvatarVerified===false)return `来源未注明头像更新日${k.avatarCheckedAt?' · 采集于 '+k.avatarCheckedAt:''}`;return k?.avatarCheckedAt?`头像采集于 ${k.avatarCheckedAt}`:'';}
function avatar(k,size=''){const url=avatarUrlFor(k),note=url?avatarSourceNote(k):'头像待补';return `<span class="avatar ${size}" title="${esc(k?.name||'未匹配达人')}${note?' · '+esc(note):''}">${esc((k?.name||'?').slice(0,2))}${url?`<img src="${esc(url)}" data-avatar-src="${esc(url)}" data-avatar-id="${esc(k.id)}" alt="${esc(k.name)}的头像" loading="lazy" referrerpolicy="no-referrer">`:''}</span>`;}
function mergeAvatarManifest(manifest=avatarManifest){
  const entries=Array.isArray(manifest)?manifest:manifest?.avatars||manifest?.profiles||manifest?.records||[];
  if(!Array.isArray(entries))return {applied:0,preserved:0,rejected:1};
  const byId=new Map(state.kols.map(k=>[String(k.id),k]));
  const byUid=new Map(),byName=new Map();
  for(const k of state.kols){if(k.uid!=null&&String(k.uid)!==''){const uid=String(k.uid);byUid.set(uid,byUid.has(uid)?null:k);}if(k.name)byName.set(k.name,byName.has(k.name)?null:k);}
  const knownSystem=new Map((research.profiles||[]).map(p=>[String(p.id),p.avatar||p.avatarUrl]));
  let applied=0,preserved=0,rejected=0;
  for(const entry of entries){
    if(!entry||typeof entry!=='object'){rejected++;continue;}
    const id=entry.id==null?'':String(entry.id),uid=entry.uid==null?'':String(entry.uid);
    const k=(id&&byId.get(id))||(uid&&byUid.get(uid))||(!id&&!uid&&byName.get(entry.name));
    const incoming=safeUrl(entry.avatar||entry.avatarUrl||'');
    if(!k||!incoming||entry.assetVerified===false||(uid&&String(k.uid||'')&&String(k.uid)!==uid)){rejected++;continue;}
    const current=k.avatar||k.avatarUrl||'';
    const custom=k.avatarUserOwned===true||k.avatarOrigin==='user'||/^data:image\//i.test(current);
    const system=!current||k.avatarOrigin==='system'||/^(?:\.\/)?assets\/avatars\//.test(current)||knownSystem.get(String(k.id))===current;
    if(custom||!system){preserved++;continue;}
    k.avatar=incoming;k.avatarOrigin='system';k.avatarSource=entry.source||entry.avatarSource||'';k.avatarCheckedAt=entry.checkedAt||entry.avatarCheckedAt||null;k.avatarAssetVerified=entry.assetVerified===true;k.avatarManifestVersion=manifest?.version||manifest?.updatedAt||null;k.historicalAvatar=entry.historicalAvatar===true;k.sourceSnapshotDate=entry.sourceSnapshotDate||null;k.currentAvatarVerified=typeof entry.currentAvatarVerified==='boolean'?entry.currentAvatarVerified:null;applied++;
  }
  return {applied,preserved,rejected};
}
function options(list,value,empty='全部'){return `<option value="">${esc(empty)}</option>`+list.map(x=>{const v=typeof x==='object'?x.id:x,l=typeof x==='object'?x.title:x;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('');}
function metric(label,value,note,ic,unit=''){return `<div class="metric"><div class="metric-label">${esc(label)}<span class="metric-icon">${icon(ic)}</span></div><div class="metric-number">${value}<span>${unit}</span></div><div class="metric-note">${esc(note)}</div></div>`;}
function bar(label,count,total,tone=''){const pct=total>0?Math.min(100,count/total*100):0;return `<div class="bar-row"><div class="bar-label"><span title="${esc(label)}">${esc(label)}</span><span class="number">${fmt(count)} <span class="muted">/ ${fmt(pct)}%</span></span></div><div class="bar-track"><div class="bar-fill ${tone}" style="width:${pct}%"></div></div></div>`;}
function countsBy(items,key){const out={};for(const i of items){const v=i[key]||'待分类';out[v]=(out[v]||0)+1;}return Object.entries(out).sort((a,b)=>b[1]-a[1]);}
function allocations(i){return (i.kolIds||[]).map(id=>{const a=(i.allocations||[]).find(a=>String(a.kolId)===String(id))||{};const k=getKol(id);return {kolId:id,quantity:num(a.quantity)??1,quoteWan:num(a.quoteWan)??num(k?.quoteWan)};});}
function costing(i){let total=0,missing=0;for(const a of allocations(i)){if(a.quoteWan==null)missing++;else total+=a.quoteWan*a.quantity;}const manual=num(i.manualBudget);return {auto:total,total:manual??total,missing,manual:manual!=null};}
function budgetUsed(name){return budgetIdeas().filter(i=>i.budgetCategory===name).reduce((s,i)=>s+costing(i).total,0);}
function allCost(){return budgetIdeas().reduce((s,i)=>s+costing(i).total,0);}
function totalBudget(){return state.budgets.reduce((s,b)=>s+(num(b.amount)||0),0);}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className=`show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',error?6500:3000);}
function emit(){for(const fn of listeners){try{fn(state);}catch(e){console.warn(e);}}}
async function persist(){if(blocked)throw Error('资料尚未成功同步，请刷新后再编辑。');state.updatedAt=new Date().toISOString();saving=true;updateSaveIndicator();try{if(window.KOLPersistence){await window.KOLPersistence.save(state);}else{localStorage.setItem(storageKey,JSON.stringify(state));}lastSaved=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});emit();}finally{saving=false;updateSaveIndicator();}}
function updateSaveIndicator(){
  const el=$('#save-state');if(!el)return;
  const savedAt=window.KOLPersistence?.savedAt;
  const time=lastSaved||(savedAt?new Date(savedAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'');
  el.textContent=window.KOLPersistence?.readonly?'同事只读 · 刷新看最新':blocked?'未能读取数据库':saving?'正在保存…':lastSaveProblem?'修改未保存':time?'已写入数据库 '+time:window.KOLPersistence?'本机数据库已连接':'浏览器本地数据';
  el.title=lastSaveProblem||'当前工作台数据保存在本机 SQLite 数据库中。';
}
async function transact(fn,message='已保存'){if(saving){render();toast('正在保存上一项修改，请稍候');return false;}const before=structuredClone(state);try{fn();KOLPlan.validate(state);KOLFactory.validate(state);await persist();lastSaveProblem='';render();toast(message);return true;}catch(e){state=before;lastSaveProblem=e.message;render();toast(`保存失败：${e.message}`,true);return false;}}
function normalize(data){data.kols=(data.kols||[]).map((k,index)=>({...k,id:String(k.id||`up-${index+1}`),name:k.name||'未命名',category:k.category||'待分类',contentType:k.contentType||'',followersWan:num(k.followersWan),quoteWan:num(k.quoteWan),selected:!!k.selected,sellingPoints:(k.sellingPoints||[]).map(Number).filter(n=>n>=1&&n<=13),sources:Array.isArray(k.sources)?k.sources:[],metrics:k.metrics||{recent20Max:null,recent20Avg:null,sampleSize:0}}));data.ideas=(data.ideas||[]).map((i,index)=>({...i,id:String(i.id||`idea-${index+1}`),title:i.title||'未命名创意',kolIds:(i.kolIds||[]).map(String),sellingPoints:(i.sellingPoints||[]).map(Number),archived:!!i.archived,inBudget:!!i.inBudget,manualBudget:num(i.manualBudget),images:i.images||[],allocations:i.allocations||[],type:i.type||'内容创意',status:i.status||'待评估'}));data.budgets=Array.isArray(data.budgets)&&data.budgets.length?data.budgets:budgetDefaults.map(([name,amount],i)=>({id:`budget-${i}`,name,amount}));data.sellingPoints=data.sellingPoints||titleById.slice(1).map((title,i)=>({id:i+1,title,description:''}));data.sources=data.sources||[];data.relationships=data.relationships||[];data.manualEdges=data.manualEdges||[];KOLPlan.initialize(data);KOLFactory.validate(data);return data;}
function mergeResearch(){for(const p of research.profiles||[]){const k=state.kols.find(k=>(p.id&&String(k.id)===String(p.id))||(p.uid&&String(k.uid)===String(p.uid))||k.name===p.name);if(!k)continue;if((p.avatar||p.avatarUrl)&&!k.avatar&&!k.avatarUrl&&k.avatarUserOwned!==true){k.avatar=p.avatar||p.avatarUrl;k.avatarOrigin='system';k.avatarSource=p.avatarSource||'';k.avatarCheckedAt=p.avatarCheckedAt||null;}if(p.recentVideos?.length){k.recentVideos=p.recentVideos;k.researchCheckedAt=p.checkedAt||p.fetchedAt;const plays=p.recentVideos.slice(0,20).map(v=>num(v.views??v.play??v.viewCount)).filter(v=>v!=null);k.metrics={...k.metrics,...p.metrics,sampleSize:plays.length,recent20Max:plays.length?Math.max(...plays):null,recent20Avg:plays.length?plays.reduce((a,b)=>a+b,0)/plays.length:null};}if(p.games?.length)k.games=p.games;if(p.collaborations?.length)k.collaborations=p.collaborations;k.referenceVideos=p.referenceVideos||k.referenceVideos;k.researchSources=p.sources||k.researchSources;if(p.researchStatus)k.researchStatus=p.researchStatus;}}
function render(){if(!state)return;graphUnmount();const focus=document.activeElement,focusId=focus?.id,selection=focus?.selectionStart;const views={factory:['脑暴工厂','CREATIVE STUDIO'],pool:['KOL + 创意中选池','CAST / SELECTION'],calendar:['排期日历','CALENDAR / SCHEDULE'],overview:['工作总览','PLAN / OVERVIEW'],kols:['UP 资料库','KOL / TALENT REGISTRY'],ideas:['创意提词板','IDEAS / CREATIVE STUDIO'],relations:['合作关系图','NETWORK / COLLABORATION'],budgets:['预算与覆盖','BUDGET / ALLOCATION'],selling:['卖点地图','PRODUCT / SELLING POINTS'],sources:['资料与数据','DATA / SOURCES']};const current=views[ui.view]||views.kols;
if(location.protocol!=='file:' && (new URLSearchParams(location.search).get('view')||'kols')!==ui.view){const next=new URL(location.href);next.searchParams.set('view',ui.view);history.replaceState(null,'',next);}
$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">A</div><div><div class="brand-name">ANANTA</div><div class="brand-sub">KOL CREATIVE LAB</div></div></div><div class="workspace-label">无限大 · 公测传播</div><div class="nav-label">WORKSPACE</div>${[['overview','grid','工作总览'],['kols','users','UP 资料库'],['ideas','bulb','创意提词板'],['factory','pair','脑暴工厂'],['pool','pair','KOL + 创意中选池'],['calendar','calendar','排期日历'],['relations','graph','合作关系图'],['budgets','wallet','预算与覆盖'],['selling','target','卖点地图']].map(([v,ic,label])=>`<button class="nav-btn ${ui.view===v?'active':''}" data-nav="${v}" title="${label}">${icon(ic)}<span class="nav-text">${label}</span>${v==='kols'?`<span class="nav-count">${state.kols.length}</span>`:v==='ideas'?`<span class="nav-count">${activeIdeas().length}</span>`:''}</button>`).join('')}<div style="height:25px"></div><div class="nav-label">MANAGE</div><button class="nav-btn ${ui.view==='sources'?'active':''}" data-nav="sources" title="资料与数据">${icon('file')}<span class="nav-text">资料与数据</span></button><div class="sidebar-bottom"><div class="side-user"><span class="user-icon">龙凯</span><div>公测策划工作区<div class="caption" style="color:#8ca4ba">ANANTA · INTERNAL</div></div></div><span>从人选，到值得做的内容。</span></div></aside><header class="topbar"><div class="breadcrumb"><span>无限大工作台</span><span>/</span><b>${current[0]}</b></div><div class="top-actions"><span class="save-state" id="save-state"></span><button class="btn small" data-action="export">${icon('download')}导出备份</button><span class="caption date">2026.11 · 公测准备</span></div></header><main class="main">${viewContent(current)}</main>`;updateSaveIndicator();if(ui.view==='relations')requestAnimationFrame(graphMount);if(focusId){const next=document.getElementById(focusId);if(next){next.focus();if(typeof selection==='number'&&next.setSelectionRange)try{next.setSelectionRange(selection,selection);}catch{}}}}
function pageHead(title,eyebrow,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="description">${description}</p></div><div class="actions">${actions}</div></div>`;}
function viewContent(current){switch(ui.view){case'pool':return KOLPlanner.poolView();case'calendar':return KOLPlanner.calendarView();case'overview':return overview();case'ideas':return ideasView();case'factory':return KOLFactory.view();case'relations':return relationsView();case'budgets':return budgetsView();case'selling':return sellingView();case'sources':return sourcesView()+KOLPlanner.historyPanel();default:return kolsView();}}
function overview(){const sel=selectedKols(),priced=sel.filter(k=>k.quoteWan!=null),covered=uniq(budgetIdeas().flatMap(i=>i.sellingPoints||[]));return pageHead('把合适的人，放进有价值的创意','PLAN / OVERVIEW','用人群与卖点解释选人，让创意、合作和预算在同一处对齐。',`<button class="btn primary" data-action="new-idea">${icon('plus')}新建创意</button>`)+`<div class="hero-banner"><div><div class="eyebrow">ANANTA · CREATIVE OPERATIONS</div><h2>让每一次合作，都有清晰的出发点</h2><p>先看人，再看他适合表达什么。把人选放入创意，预算与卖点覆盖随之更新。</p><div class="budget-progress"><i style="width:${Math.min(100,allCost()/totalBudget()*100)}%"></i></div></div><div class="budget-head-amount"><small>已纳入计划 / 总预算 · 万元</small><div><b>${fmt(allCost())}</b><span style="color:#8aa8ca"> / ${fmt(totalBudget())}</span></div><p>${budgetIdeas().length} 项创意计入 · 待询价部分不虚填</p></div></div><div class="metric-grid">${metric('UP资料',fmt(state.kols.length),'已归集资料；基础数据保留来源','users','位')}${metric('当前入选',fmt(sel.length),'入选为策划选择，不等于商务锁档','check','位')}${metric('活跃创意',fmt(activeIdeas().length),`${state.ideas.filter(i=>i.archived).length} 项历史创意归档保留`,'bulb','项')}${metric('计划卖点覆盖',`${covered.length}<span>/ 13</span>`,'按纳入预算的创意去重计数','target','项')}</div><div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>预算分配</h3><p>已知报价小计，手动覆盖金额优先</p></div><button class="btn small" data-nav="budgets">查看全部 ${icon('arrow')}</button></div><div class="panel-body bar-list">${state.budgets.slice(0,7).map(b=>{const u=budgetUsed(b.name);return `<div class="bar-row"><div class="bar-label"><span>${esc(b.name)}</span><span class="number">${fmt(u)} <span class="muted">/ ${fmt(b.amount)} 万</span></span></div><div class="bar-track"><div class="bar-fill ${u>b.amount?'red':''}" style="width:${Math.min(100,b.amount?u/b.amount*100:0)}%"></div></div></div>`;}).join('')}</div></div><div class="panel"><div class="panel-head"><div><h3>入选人群与内容分布</h3><p>统计当前入选UP；一位UP计入一个主分区</p></div><button class="btn small" data-nav="kols">管理人选 ${icon('arrow')}</button></div><div class="panel-body bar-list">${countsBy(sel,'category').slice(0,8).map(([c,n])=>bar(c,n,sel.length)).join('')||'<p class="caption">还没有入选达人</p>'}</div></div></div><div class="panel section-gap"><div class="panel-head"><div><h3>接下来值得补齐</h3><p>将信息缺口转成可核查的下一步</p></div></div><div class="metric-grid" style="margin:0;border:0;gap:0">${metric('入选UP报价待补',fmt(sel.length-priced.length),'在UP详情记录形式、单位与来源','wallet','位')}${metric('近期作品待采集',fmt(sel.filter(k=>!KOLPerformance.profile(k).sampleSize&&KOLPerformance.profile(k).status!=='确认零投稿').length),'近20条需真实作品列表，不能用预估播放替代','file','位')}${metric('创意人员待匹配',fmt(activeIdeas().filter(i=>!i.kolIds?.length).length),'进入创意卡，从UP库添加参与人','users','项')}${metric('创意卖点待选择',fmt(activeIdeas().filter(i=>!i.sellingPoints?.length).length),'为每个创意说明表达的产品体验','target','项')}</div></div>`;}
function kolsView(){const sel=selectedKols();let list=state.kols.filter(k=>(!ui.q||[k.name,k.uid,k.category,k.contentType,k.supplier,k.matchReason].join(' ').toLowerCase().includes(ui.q.trim().toLowerCase()))&&(!ui.category||k.category===ui.category)&&(!ui.content||k.contentType===ui.content||(k.contentTypes||[]).includes(ui.content))&&(!ui.sell||k.sellingPoints.includes(Number(ui.sell)))&&(!ui.selection||(ui.selection==='yes'?k.selected:!k.selected))&&(!ui.status||(k.status||'待核实')===ui.status)&&KOLPerformance.matches(k,ui.performanceFilter));list.sort((a,b)=>ui.sort==='plays'?(KOLPerformance.profile(b).avg??-1)-(KOLPerformance.profile(a).avg??-1):ui.sort==='fans'?(b.followersWan??-1)-(a.followersWan??-1):ui.sort==='price'?(a.quoteWan??Infinity)-(b.quoteWan??Infinity):ui.sort==='name'?a.name.localeCompare(b.name,'zh-CN'):Number(b.selected)-Number(a.selected)||a.name.localeCompare(b.name,'zh-CN'));const page=Math.min(ui.page,Math.max(1,Math.ceil(list.length/36))),current=list.slice((page-1)*36,page*36);const qpriced=sel.filter(k=>k.quoteWan!=null);return pageHead('UP 资料库','KOL / TALENT REGISTRY','找到适合的人，也看清推荐依据。主分区、内容形式与卖点标签分别筛选。',`<button class="btn" data-action="new-kol">${icon('plus')}新增UP</button><button class="btn primary" data-action="idea-from-selected">${icon('bulb')}用已选UP建创意</button>`)+`<div class="metric-grid">${metric('已入库',fmt(state.kols.length),'按可用账号身份与名称归并','users','位')}${metric('本轮入选',fmt(sel.length),'与全部候选池分开管理','check','位')}${metric('入选报价已知',fmt(qpriced.length),`${sel.length-qpriced.length} 位待询价 · 不同形式另核`,'wallet','位')}${metric('主分区',fmt(uniq(state.kols.map(k=>k.category)).length),'保留达人分类与跨类能力','grid','类')}</div><div class="split"><section><div class="filterbar"><div class="search">${icon('search')}<input id="kol-search" placeholder="搜索UP、分区、供应商…" value="${esc(ui.q)}" data-filter="q" aria-label="搜索UP"></div><select data-filter="category" aria-label="主分区">${options(uniq(state.kols.map(k=>k.category)).sort(),ui.category,'全部分区')}</select><select data-filter="content" aria-label="内容类型">${options(uniq(state.kols.flatMap(k=>k.contentTypes?.length?k.contentTypes:[k.contentType]).filter(Boolean)).sort(),ui.content,'全部内容类型')}</select><select data-filter="sell" aria-label="推荐卖点">${options(state.sellingPoints,ui.sell,'全部卖点')}</select><select data-filter="selection" aria-label="入选状态">${options([{id:'yes',title:'已选UP'},{id:'no',title:'待选UP'}],ui.selection,'全部人选')}</select><select data-filter="status" aria-label="推进状态">${options(uniq(state.kols.map(k=>k.status||'待核实')).sort(),ui.status,'全部推进状态')}</select></div><div class="view-strip"><span>找到 <strong>${list.length}</strong> 位UP · 点击卡片查看依据和完整资料</span><select data-filter="performanceFilter" aria-label="作品数据筛选">${options([{id:'has',title:'有近期投稿样本'},{id:'full',title:'完整20条'},{id:'case',title:'近90天合作有播放'},{id:'pending',title:'待核播放'}],ui.performanceFilter||'','全部作品数据')}</select><select data-filter="sort" aria-label="排序">${options([{id:'selected',title:'已选优先'},{id:'plays',title:'近期均播高优先'},{id:'fans',title:'粉丝数从高到低'},{id:'price',title:'报价从低到高'},{id:'name',title:'名称排序'}],ui.sort,'默认排序')}</select></div><div class="kol-grid">${current.map(k=>kolCard(k)).join('')||empty('没有匹配的UP','调整分区或卖点筛选，再试试其他关键词。')}</div><div class="pagination"><span>第 ${page} / ${Math.max(1,Math.ceil(list.length/36))} 页 · 每页36位</span><div class="actions"><button class="btn small" data-page="${page-1}" ${page===1?'disabled':''}>上一页</button><button class="btn small" data-page="${page+1}" ${page*36>=list.length?'disabled':''}>下一页</button></div></div><p class="bottom-note">卖点匹配为策划建议；实际游戏能力、达人档期和商务权益仍需逐项确认。近期20条作品统计仅使用已采集的作品列表。</p></section>${selectionAside(sel)}</div>`;}
function kolCard(k){return `<article class="kol-card ${k.selected?'selected':''}" data-kol="${esc(k.id)}" tabindex="0" role="button" aria-label="查看${esc(k.name)}"><input class="kol-check" type="checkbox" data-select-kol="${esc(k.id)}" ${k.selected?'checked':''} aria-label="${k.selected?'取消选择':'选择'}${esc(k.name)}"><div class="kol-top">${avatar(k)}<div><div class="kol-name">${esc(k.name)}</div><div class="kol-type">${esc(k.category)}${k.contentType?' · '+esc(k.contentType):''}</div></div></div><div class="kol-metrics"><div><div class="label">粉丝数</div><div class="num">${fmt(k.followersWan)}<small>万</small></div></div><div><div class="label">参考报价</div><div class="num">${fmt(k.quoteWan)}<small>${k.quoteWan==null?'待询价':'万元'}</small></div></div></div>${KOLPerformance.card(k)}<div class="tags">${(k.sellingPoints||[]).slice(0,2).map(id=>pill(shortSell(id),'blue')).join('')||pill('卖点待匹配')}${k.sellingPoints?.length>2?pill('+'+(k.sellingPoints.length-2)):''}</div><div class="kol-foot"><span class="line-clamp"><i class="status-dot"></i>${esc(k.status||'待核实')}</span><span>${KOLPerformance.profile(k).caseCount?KOLPerformance.profile(k).caseCount+' 条合作记录':''}</span></div></article>`;}
function selectionAside(sel){return `<aside class="panel sidebar-panel"><div class="selection-summary"><span style="font-size:12px">当前人选池</span><div class="big">${sel.length}<small style="font:11px system-ui;margin-left:7px">位 UP</small></div><p>勾选即更新占比，创意预算单独计算</p></div><div class="aside-section"><h3>主分区占比 <span class="muted">/ SELECTED</span></h3><div class="bar-list">${countsBy(sel,'category').map(([c,n])=>bar(c,n,sel.length)).join('')||'<p class="caption">选择UP后，分区占比将在这里显示。</p>'}</div></div><div class="aside-section"><h3>推荐卖点覆盖</h3>${state.sellingPoints.map(p=>{const n=sel.filter(k=>k.sellingPoints?.includes(Number(p.id))).length;return `<div class="coverage-line"><span class="badge-no">${String(p.id).padStart(2,'0')}</span><span class="sell-title">${esc(shortSell(p.id))}</span><strong style="color:${n?'#3561d0':'#aebbc9'}">${n}</strong></div>`;}).join('')}<p class="caption">一位UP可匹配多个卖点，因此数量不相加为总人数。</p></div></aside>`;}
function empty(title,text){return `<div class="empty no-results">${icon('search')}<h3>${title}</h3><p>${text}</p></div>`;}
function ideasView(){let list=state.ideas.filter(i=>(ui.ideaStatus==='archived'?i.archived:ui.ideaStatus==='budget'?i.inBudget&&!i.archived:!i.archived)&&(!ui.ideaQ||[i.title,i.description,i.type,...(i.kolIds||[]).map(id=>getKol(id)?.name)].join(' ').toLowerCase().includes(ui.ideaQ.toLowerCase()))&&(!ui.ideaType||i.type===ui.ideaType)&&(!ui.ideaSell||i.sellingPoints.includes(Number(ui.ideaSell)))&&(!ui.ideaBudget||i.budgetCategory===ui.ideaBudget));return pageHead('创意提词板','IDEAS / CREATIVE STUDIO','从一个卖点出发，写下内容，把合适的UP拉进来。每张卡都连接人选与预算。',KOLFactory.openButton()+`<button class="btn primary" data-action="new-idea">${icon('plus')}新建创意</button>`)+`<div class="budget-grid">${state.budgets.map(b=>`<button class="budget-mini ${ui.ideaBudget===b.name?'active':''}" data-budget-filter="${esc(b.name)}"><div class="name">${esc(b.name)}</div><div class="total">${fmt(budgetUsed(b.name))}<small>/ ${fmt(b.amount)}万</small></div><div class="bar-track"><div class="bar-fill ${budgetUsed(b.name)>b.amount?'red':''}" style="width:${Math.min(100,b.amount?budgetUsed(b.name)/b.amount*100:0)}%"></div></div><div class="mini-meta"><span>${budgetIdeas().filter(i=>i.budgetCategory===b.name).length}项计划</span><span>查看分类</span></div></button>`).join('')}</div><div class="filterbar"><div class="search">${icon('search')}<input id="idea-search" data-filter="ideaQ" placeholder="搜索创意、UP或内容关键词…" value="${esc(ui.ideaQ)}" aria-label="搜索创意"></div><select data-filter="ideaType" aria-label="创意类型">${options(uniq(state.ideas.map(i=>i.type)).sort(),ui.ideaType,'全部创意类型')}</select><select data-filter="ideaSell" aria-label="创意卖点">${options(state.sellingPoints,ui.ideaSell,'全部卖点')}</select><select data-filter="ideaBudget" aria-label="预算分类">${options(state.budgets.map(b=>b.name),ui.ideaBudget,'全部预算分类')}</select></div><div class="tabs">${[['active','全部待选创意',activeIdeas().length],['budget','已纳入预算',budgetIdeas().length],['archived','历史归档',state.ideas.filter(i=>i.archived).length]].map(([v,l,n])=>`<button class="tab ${ui.ideaStatus===v?'active':''}" data-idea-status="${v}">${l} <span class="number">${n}</span></button>`).join('')}</div><div class="view-strip"><span>当前 <strong>${list.length}</strong> 项 · 导入候选创意需手动纳入预算</span><span>计划金额 ${fmt(allCost())} / ${fmt(totalBudget())} 万</span></div><div class="idea-grid">${list.map(ideaCard).join('')||empty('这里还没有创意','新建一张卡，或调整筛选查看已有创意。')}</div><p class="bottom-note">卡片金额为本创意所选参与人的已知报价合计；缺价另列。只有“纳入预算”的活跃创意进入预算看板。</p>`;}
function ideaCard(i){const cost=costing(i),people=(i.kolIds||[]).map(getKol).filter(Boolean),image=safeUrl(i.images?.[0]?.url||i.images?.[0]);return `<article class="idea-card" tabindex="0" role="button" data-idea="${esc(i.id)}" aria-label="查看创意${esc(i.title)}">${image?`<img class="idea-cover" src="${esc(image)}" alt="${esc(i.title)}示意图" loading="lazy">`:''}<div class="idea-body"><div class="idea-meta"><span>${esc(i.id)} · ${esc(i.type)}</span>${pill(i.archived?'已归档':i.inBudget?'已纳入预算':i.status||'待评估',i.inBudget&&!i.archived?'green':'')}</div><h3>${esc(i.title)}</h3><p class="idea-desc">${esc(i.description||'补充内容设想，让所有人知道这个创意想表达什么。')}</p><div class="idea-sell">${icon('target')}<div class="tags">${(i.sellingPoints||[]).slice(0,3).map(id=>pill(shortSell(id),'blue')).join('')||pill('卖点待补')}</div></div></div>${KOLPlanner.ideaButton(i)}<div class="idea-footer"><div class="idea-people"><div class="avatar-stack">${people.slice(0,4).map(k=>avatar(k,'sm')).join('')}</div><span class="names">${people.length?esc(people.map(k=>k.name).join('、')):'匹配UP'}${people.length>4?` +${people.length-4}`:''}</span></div><div class="idea-budget">${fmt(cost.total)}<small> 万${cost.manual?' · 手填':''}</small>${cost.missing&&!cost.manual?`<div class="notice-inline">${cost.missing}位待询价</div>`:''}</div></div>${KOLFactory.cardButton(i)}</article>`;}
function budgetsView(){const used=allCost(),limit=totalBudget(),planned=budgetIdeas();const dup={};planned.forEach(i=>(i.kolIds||[]).forEach(id=>(dup[id]??=[]).push(i)));const duplicates=Object.entries(dup).filter(([,a])=>a.length>1);return pageHead('预算与卖点覆盖','BUDGET / ALLOCATION','按创意归属核对预算，同时看内容类型与产品卖点的覆盖。单位：万元。',`<button class="btn" data-action="edit-budgets">${icon('edit')}调整预算额度</button>`)+`<div class="metric-grid">${metric('计划总额',fmt(limit),'按用户提供的十类预算录入，可调整','wallet','万')}${metric('已纳入创意',fmt(used),`${planned.length}项 · 含手动填写金额`,'bulb','万')}${metric('剩余计划额度',fmt(limit-used),used>limit?'当前计划已超出总额度':'不代表实际付款或采购结余','grid','万')}${metric('缺价创意',fmt(planned.filter(i=>costing(i).missing&&!costing(i).manual).length),'缺价不按0元合作处理','file','项')}</div><div class="panel"><div class="panel-head"><div><h3>预算分类明细</h3><p>点击分类，回到对应创意卡片</p></div><span class="pill blue">策划测算 · 非采购实付</span></div><div class="table-wrap"><table class="budget-table"><thead><tr><th>预算分类</th><th>计划额度</th><th>已纳入金额</th><th>剩余额度</th><th>占用比例</th><th>创意数</th><th></th></tr></thead><tbody>${state.budgets.map(b=>{const u=budgetUsed(b.name);return `<tr><td class="name-cell">${esc(b.name)}</td><td class="number">${fmt(b.amount)}</td><td class="number">${fmt(u)}</td><td class="number ${u>b.amount?'warn-text':''}">${fmt(b.amount-u)}</td><td style="min-width:110px"><div class="bar-track"><div class="bar-fill ${u>b.amount?'red':''}" style="width:${Math.min(100,b.amount?u/b.amount*100:0)}%"></div></div><span class="caption number">${b.amount?fmt(u/b.amount*100):'—'}%</span></td><td class="number">${planned.filter(i=>i.budgetCategory===b.name).length}</td><td><button class="btn small" data-budget-view="${esc(b.name)}">查看创意</button></td></tr>`;}).join('')}</tbody></table></div></div><div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>卖点覆盖 · 创意数量</h3><p>仅统计纳入预算的创意；一项可覆盖多个卖点</p></div></div><div class="panel-body bar-list">${state.sellingPoints.map(p=>bar(shortSell(p.id),planned.filter(i=>i.sellingPoints?.includes(Number(p.id))).length,planned.length)).join('')}</div></div><div><div class="panel"><div class="panel-head"><div><h3>创意类型占比</h3><p>按纳入预算的创意数统计</p></div></div><div class="panel-body bar-list">${countsBy(planned,'type').map(([c,n])=>bar(c,n,planned.length,'green')).join('')||'<p class="caption">把创意纳入预算后，这里会显示类型分布。</p>'}</div></div><div class="panel section-gap"><div class="panel-head"><div><h3>重复计费检查</h3><p>同一UP出现在多项计划中，先核打包与复用</p></div></div><div class="panel-body">${duplicates.map(([id,a])=>`<div class="summary-row"><span>${esc(getKol(id)?.name||id)}</span><span>${a.length}项创意</span></div>`).join('')||'<p class="caption">目前未发现同一UP重复进入多项预算创意。</p>'}<p class="bottom-note">相同UP参与不同作品可以分别计费；此处仅提示复核，不自动去重金额。</p></div></div></div></div>`;}
function sellingView(){return pageHead('13个卖点，13种体验出发点','PRODUCT / SELLING POINTS','先让观众感受到游戏的乐趣，再选择适合表达它的人与内容。')+`<div class="sell-grid">${state.sellingPoints.map(p=>`<article class="sell-card"><div class="sell-num">${String(p.id).padStart(2,'0')}</div><h3>${esc(shortSell(p.id))}</h3><p>${esc(p.description||p.title)}</p><div class="sell-bottom"><button class="btn small" data-sell-kols="${p.id}">${state.kols.filter(k=>k.sellingPoints.includes(Number(p.id))).length}位推荐UP</button><button class="btn small" data-sell-ideas="${p.id}">${activeIdeas().filter(i=>i.sellingPoints.includes(Number(p.id))).length}项创意</button></div></article>`).join('')}</div><p class="bottom-note">此处为本轮内部策划卖点。具体实现、版本范围和对外披露边界以产品确认及当前Brief为准。</p>`;}
function sourcesView(){const avatars=avatarStats(),recent=state.kols.filter(k=>KOLPerformance.profile(k).sampleSize).length;return pageHead('资料与数据','DATA / SOURCES','保留原始出处，分清已知事实、历史记录与策划建议。',`<button class="btn" data-action="import">${icon('upload')}导入备份</button><button class="btn primary" data-action="export">${icon('download')}导出全部数据</button>`)+`<div class="metric-grid">${metric('来源文件',fmt(state.sources.length),'导入时保留文件、Sheet和行号','file','份')}${metric('已核验头像',`<span data-avatar-count>${fmt(avatars.verified)}</span>`,'本地文件已核验或浏览器加载成功','users','位')}${metric('近期作品有记录',fmt(recent),'展示样本数与采集日期','grid','位')}${metric('全部创意',fmt(state.ideas.length),'含历史归档，保留原始取舍理由','bulb','项')}</div><div class="note">${window.KOLPersistence?'当前修改保存到本机资料服务。':'当前修改保存在本机浏览器。'}<span data-avatar-summary>${avatars.matched}位已有头像路径 · ${avatars.failed}位加载失败</span>。导出JSON可备份达人、创意、预算、图片和人工补充记录。导入会替换当前工作区数据，导入前建议先导出备份。</div><div class="grid-two"><div class="panel"><div class="panel-head"><h3>归集的来源文件</h3><span class="caption">${state.sources.length}份</span></div><div class="source-list">${state.sources.map((s,i)=>`<div class="source-card"><strong>${esc(s.file||s.name||s.filename||s.path||`来源${i+1}`)}</strong><p>${esc(s.role||s.purpose||s.scope||s.description||'用于资料归集；字段依据见UP与创意详情。')}</p>${s.sha256?`<p>SHA256 · ${esc(s.sha256)}</p>`:''}</div>`).join('')||empty('来源信息待补','导入数据时保留出处，可继续补录。')}</div></div><div class="panel"><div class="panel-head"><h3>使用口径</h3></div><div class="panel-body"><h3>筛选与合作状态分开</h3><p class="description">勾选入选表示本轮策划选择。有档期、已回价和人选认可，不自动等同已签约或下单。</p><h3 class="section-gap">报价跟随合作形式</h3><p class="description">报价以万元展示。直播小时、视频条数、打包权益不可直接混加；在创意详情核对单价与数量。</p><h3 class="section-gap">标签是可追溯的推荐</h3><p class="description">卖点标签先依据已有内容定位和历史创意匹配，可人工修改；证据不足时不伪造合作史或播放数据。</p><h3 class="section-gap">关系图不是熟悉度结论</h3><p class="description">实线来自已有合作记录，虚线来自创意同组建议。记录次数只说明已找到的证据，节目效果需要进一步判断。</p><h3 class="section-gap">图片与备份</h3><p class="description">创意示意图支持上传3张，单张自动压缩以便保存。原始高精度素材请另行留存。</p></div></div></div>`;}
function resolveKol(v){if(v==null||String(v).trim()==='')return undefined;return state.kols.find(k=>String(k.id)===String(v)||String(k.uid)===String(v)||k.name===v);}
const graphUI={depth:'all',minCount:'1',form:'all',evidence:'all',years:'all',people:'all',showProposed:false,showIsolates:true,includeUnknownDates:false,details:true,transform:null,overrides:{},pending:null};
const graphRuntime={graph:null,layout:null,visualEdges:[],observer:null,svg:null,width:800,height:600,drag:null,pointers:new Map()};
function graphCore(){return window.KOLGraphCore;}
function graphModel(){return graphCore().buildGraph(state.kols,[...(state.relationships||[]),...(research.edges||[]),...(state.manualEdges||[]).map(e=>({...e,origin:'manual'}))],state.ideas);}
function allEdges(){return graphModel().edges;}
function visualGraphEdges(graph){const pairs=new Map();for(const e of graph.edges){const id=[e.a,e.b].sort().join('|');if(!pairs.has(id))pairs.set(id,{id,a:e.a,b:e.b,history:null,proposed:null});pairs.get(id)[e.kind==='history'?'history':'proposed']=e;}return [...pairs.values()];}
function buildVisibleGraph(){const model=graphModel();if(!ui.focus||!model.byId.has(ui.focus)){ui.focus=model.nodes.find(k=>k.name==='老番茄')?.id||model.edges.find(e=>e.kind==='history')?.a||model.nodes[0]?.id;}const graph=graphCore().filterGraph(model,{...graphUI,focus:ui.focus,asOf:graphCore().todayShanghai()});graphRuntime.graph=graph;graphRuntime.layout=graphCore().layoutGraph(graph,graphUI.overrides);graphRuntime.visualEdges=visualGraphEdges(graph);if(!graph.edges.some(e=>e.id===ui.edge))ui.edge='';return graph;}
function graphSelect(key,label,choices){return `<label class="network-filter"><span>${label}</span><select data-network-filter="${key}" aria-label="${label}">${choices.map(([value,title])=>`<option value="${value}" ${String(graphUI[key])===String(value)?'selected':''}>${title}</option>`).join('')}</select></label>`;}
function relationsView(){if(!graphCore())return empty('关系画布正在加载','请稍候');const g=buildVisibleGraph(),focus=getKol(ui.focus);return pageHead('合作关系图','NETWORK / COLLABORATION','在全局网络中找搭档。共同作品、创意建议与暂未收录证据的UP分开查看。',`<button class="btn" data-network-action="toggle-details">${icon('file')}${graphUI.details?'收起详情':'展开详情'}</button><button class="btn primary" data-action="new-edge">${icon('plus')}补充合作记录</button>`)+`<div class="network-filters"><div class="network-search search">${icon('search')}<input id="network-search" list="network-kol-options" placeholder="搜索UP名称 / UID，定位到画布中心" value="${esc(focus?.name||'')}" aria-label="搜索并定位UP"><datalist id="network-kol-options">${state.kols.map(k=>`<option value="${esc(k.name)}"></option>`).join('')}</datalist><button class="network-search-go" data-network-action="search" aria-label="定位达人">${icon('arrow')}</button></div>${graphSelect('depth','关系深度',[['all','全网'],['1','1度关系'],['2','2度关系'],['3','3度关系']])}${graphSelect('minCount','共同作品',[['1','≥ 1件'],['2','≥ 2件'],['3','≥ 3件'],['5','≥ 5件'],['10','≥ 10件']])}${graphSelect('form','合作形式',[['all','全部形式'],...Object.entries(graphCore().FORMS)])}${graphSelect('evidence','证据来源',[['all','全部来源'],...Object.entries(graphCore().LEVELS)])}${graphSelect('years','作品时间',[['all','全部时间'],['1','近1年'],['3','近3年']])}${graphSelect('people','人选范围',[['all','全部UP'],['selected','本轮已选']])}<div class="network-switches"><label><input type="checkbox" data-network-filter="showProposed" ${graphUI.showProposed?'checked':''}>显示创意建议</label><label><input type="checkbox" data-network-filter="showIsolates" ${graphUI.showIsolates?'checked':''}>显示暂未收录证据UP</label>${graphUI.years!=='all'?`<label><input type="checkbox" data-network-filter="includeUnknownDates" ${graphUI.includeUnknownDates?'checked':''}>含日期未知作品</label>`:''}<button class="btn subtle small" data-network-action="reset-filters">重置筛选</button></div></div><div class="network-workspace ${graphUI.details?'with-details':''}"><section class="network-main panel"><div class="network-status"><span><strong>${g.nodes.length}</strong> 位UP <i>·</i> <strong>${g.history.length}</strong> 对共同作品关系 <i>·</i> <strong>${new Set(g.history.flatMap(e=>e.records.map(r=>r.workId))).size}</strong> 件去重作品/活动 <i>·</i> <strong>${g.isolates.length}</strong> 位暂无收录${g.hiddenCount?` <span class="muted">· ${g.hiddenCount}位被筛选隐藏</span>`:''}</span><span class="caption">截至 ${graphCore().todayShanghai()} · 拖动平移 / 节点排布 · 滚轮缩放</span></div><div id="network-stage" class="network-stage"><svg id="network-svg" class="network-svg" role="application" aria-label="全局UP合作关系画布，方向键平移，加减号缩放" tabindex="0"><defs><pattern id="network-grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#ccd8e7"/></pattern></defs><rect width="100%" height="100%" fill="url(#network-grid)"/><g id="network-viewport">${networkSvgContent(g)}</g></svg>${!g.nodes.length?'<div class="network-empty"><h3>当前筛选下没有UP</h3><p>降低共同作品门槛、扩大证据范围，或重置筛选。</p><button class="btn" data-network-action="reset-filters">重置筛选</button></div>':''}<div class="network-controls"><button data-network-action="zoom-in" title="放大" aria-label="放大">+</button><button data-network-action="zoom-out" title="缩小" aria-label="缩小">−</button><button data-network-action="actual" id="network-zoom" title="恢复100%">100%</button><span></span><button data-network-action="fit-connected" title="适配有共同作品的群组">关系群</button><button data-network-action="fit-all" title="适配当前可见的全部UP">全体概览</button><button data-network-action="locate" title="把当前UP放到画布中心">定位当前</button><button data-network-action="reset-layout" title="清除本次拖动排布">重排</button></div><div class="network-corner"><span class="network-live-dot"></span> 当前聚焦：${esc(focus?.name||'未选择')}${!g.nodes.some(n=>n.id===ui.focus)?'（被当前筛选隐藏）':''}</div></div><div class="network-legend"><span><i class="network-line-key"></i>共同作品关系</span><span><i class="network-line-key dashed"></i>创意建议</span><span><i class="network-dot-key"></i>暂未收录合作证据</span><span class="network-help">度数＝真实记录网络跳数，不代表熟悉度；建议边不计次数或跳数。</span></div></section><aside id="network-details" class="network-details panel" ${graphUI.details?'':'hidden'}>${networkDetails()}</aside></div>`;}
function networkSvgContent(graph){const layout=graphRuntime.layout;const label=layout.isolateLabel;const edges=graphRuntime.visualEdges.map((e,index)=>{const a=layout.positions.get(e.a),b=layout.positions.get(e.b);if(!a||!b)return '';return `<g class="network-link ${e.history?'history':'proposed'}" data-network-pair="${esc(e.id)}"><line class="network-link-hit" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><line class="network-link-visible" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><g class="network-edge-label" transform="translate(${(a.x+b.x)/2},${(a.y+b.y)/2})"><rect x="-43" y="-11" width="86" height="22" rx="8"/><text text-anchor="middle" y="4">${e.history?`${e.history.count}件作品${e.proposed?' +建议':''}`:'创意建议'}</text></g><title>${esc(getKol(e.a)?.name)} × ${esc(getKol(e.b)?.name)} · ${e.history?e.history.count+'件共同作品':'仅创意建议'}</title></g>`;}).join('');const nodes=graph.nodes.map((k,index)=>{const p=layout.positions.get(k.id),connected=graph.connectedIds.has(k.id),isFocus=k.id===ui.focus,r=connected||isFocus?22:7,url=avatarUrlFor(k),labelName=!isFocus&&k.name.length>16?k.name.slice(0,15)+'…':k.name;return `<g class="network-node ${connected?'connected':'unrecorded'} ${isFocus?'focused':''} ${graph.distances.get(k.id)===1?'neighbor':''}" transform="translate(${p.x},${p.y})" data-network-node="${esc(k.id)}" tabindex="${connected||isFocus?0:-1}" role="button" aria-label="${esc(k.name)}，${connected?'有共同作品记录':'暂未收录合作证据'}"><circle class="network-node-halo" r="${r+6}"/><circle class="network-node-base" r="${r}"/>${url&&(connected||isFocus)?`<clipPath id="network-face-${index}"><circle r="${r}"/></clipPath><image href="${esc(url)}" data-avatar-src="${esc(url)}" data-avatar-id="${esc(k.id)}" x="${-r}" y="${-r}" width="${r*2}" height="${r*2}" clip-path="url(#network-face-${index})"/>`:(connected||isFocus)?`<text class="network-initials" text-anchor="middle" y="5">${esc(k.name.slice(0,2))}</text>`:''}<text class="network-label" text-anchor="middle" y="${r+21}">${esc(labelName)}</text><title>${esc(k.name)} · ${esc(k.category)}${k.selected?' · 本轮已选':''}${connected?'':' · 暂未收录合作证据'}${url&&avatarSourceNote(k)?' · '+esc(avatarSourceNote(k)):''}</title></g>`;}).join('');return `${label?`<g class="network-area-label" transform="translate(${label.x},${label.y})"><text>暂未收录合作证据 · ${label.count}位</text><text y="22" class="sub">资料库中的独立节点，不表示现实中没有合作关系</text></g>`:''}${edges}${nodes}`;}
function selectedNetworkEdge(){return graphRuntime.graph?.edges.find(e=>e.id===ui.edge)||null;}
function networkDetails(){const graph=graphRuntime.graph,focus=getKol(ui.focus),edge=selectedNetworkEdge();if(!graph)return '';if(edge)return `<div class="network-details-head"><button class="btn small" data-network-action="clear-edge">← 回到${esc(focus?.name||'UP')}</button><button class="close" data-network-action="toggle-details" aria-label="收起详情">×</button></div><div class="network-details-body">${edgeDetail(edge)}</div>`;const related=graphRuntime.visualEdges.filter(e=>e.a===ui.focus||e.b===ui.focus);const isVisible=graph.nodes.some(n=>n.id===ui.focus);return `<div class="network-details-head"><h3>当前UP</h3><button class="close" data-network-action="toggle-details" aria-label="收起详情">×</button></div><div class="network-details-body"><div class="network-person">${avatar(focus,'lg')}<div><h2>${esc(focus?.name||'选择UP')}</h2><p class="caption">${esc(focus?.category||'')}</p></div></div><div class="tags">${focus?.selected?pill('本轮已选','green'):pill('候选UP')}${pill(`${related.filter(e=>e.history).length}位有共同作品的UP`,'blue')}</div><div class="actions section-gap"><button class="btn small" data-kol="${esc(ui.focus)}">查看完整资料</button><button class="btn small" data-network-action="locate">定位到中心</button></div>${!isVisible?'<div class="note warn section-gap">这位UP被当前筛选隐藏。点击“定位到中心”可清除冲突筛选后显示。</div>':''}<h3 class="section-gap">相邻关系 <span class="caption">${related.length}对</span></h3>${related.length?related.sort((a,b)=>(b.history?.count||0)-(a.history?.count||0)).map(e=>{const k=getKol(e.a===ui.focus?e.b:e.a);return `<button class="network-relation-row" data-network-pair="${esc(e.id)}">${avatar(k,'sm')}<span><strong>${esc(k?.name)}</strong><small>${e.history?`${e.history.count}件共同作品`:'尚无共同作品证据'}${e.proposed?' · 有创意建议':''}</small></span>${icon('arrow')}</button>`;}).join(''):'<div class="note section-gap">当前筛选下尚未收录这位UP的共同作品证据。可扩大筛选范围，或补充带作品链接的记录。</div>'}<div class="network-explain"><h3>怎样理解这张图</h3><p>连线上的数字是去重后的共同作品数量，不是全部历史或实际合作场次。</p><p>共创署名只说明在同一作品中署名；筛选“同框出镜”“同局联机”可查看更具体的合作方式。</p><p>其他UP仍留在画布中。用“全体概览”查看当前全部节点，用“关系群”聚焦有证据的群组。</p></div></div>`;}
function edgeDetail(e){const a=getKol(e.a),b=getKol(e.b),companion=graphRuntime.graph?.proposed.find(x=>x.a===e.a&&x.b===e.b),ideas=e.kind==='proposed'?e.ideas:(companion?.ideas||[]);return `<h3>${esc(a?.name)} × ${esc(b?.name)}</h3>${pill(e.kind==='history'?'共同作品证据':'策划组合建议',e.kind==='history'?'blue':'amber')}<div class="relationship-metrics"><div><b>${e.kind==='history'?e.count:ideas.length}</b><small>${e.kind==='history'?'当前筛选的共同作品':'同组创意'}</small></div><div><b>${e.sellingPoints.length}</b><small>${esc(e.recommendationScope||'建议覆盖卖点')}</small></div></div>${e.kind==='history'?`<p class="note">已找到去重作品/活动，非全部历史或实际合作场次。${e.totalRecordedCount!==undefined&&e.totalRecordedCount!==e.count?`全部已收录${e.totalRecordedCount}件，当前筛选后${e.count}件。`:''}同一BV的多P按1件作品计数。</p><p class="caption" style="margin-top:8px">含搜索摘要的记录未表示已观看完整视频；共创署名不自动证明同框或同局。具体来源见每件作品的徽标。</p>`:''}${(e.records||[]).map(r=>`<div class="relation-record"><strong>${external(r.url,r.title||r.workId)}</strong><div class="tags" style="margin-top:8px">${(r.forms||[r.type]).map(t=>pill(graphCore().FORMS[t]||'形式待核','blue')).join('')}${(r.levels||[r.evidenceLevel]).map(t=>pill(graphCore().LEVELS[t]||t)).join('')}</div><p>${esc(r.contentSummary||'内容形式待补充')}</p><p class="caption">作品ID：${esc(r.workId)}<br>发布日期：${esc(r.date||'未知')}<br>证据核查：${esc(r.sourceCheckedAt||'日期待补')}</p>${r.dateConflicts?.length>1?`<p class="caption warn-text">来源日期有差异：${r.dateConflicts.map(esc).join(' / ')}；当前展示匹配筛选的来源。</p>`:''}${r.verificationNote?`<details><summary>核查备注</summary><p class="caption">${esc(r.verificationNote)}</p></details>`:''}</div>`).join('')}${ideas.length?`<h3 class="section-gap">创意同组建议</h3>${ideas.map(i=>`<div class="relation-record"><button class="btn small" data-idea="${esc(i.id)}">${esc(i.title)} ${icon('arrow')}</button><p>${esc(i.description||'')}</p></div>`).join('')}`:''}<div class="tags">${e.sellingPoints.map(id=>pill(shortSell(id),'blue')).join('')}</div>${combinationReason(e)}<p class="bottom-note">${(e.sourceNotes||[]).map(esc).join(' ')} 作品与网络距离不能直接证明私交、熟悉度或节目效果。</p>`;}
function graphUnmount(){if(graphRuntime.observer){graphRuntime.observer.disconnect();graphRuntime.observer=null;}graphRuntime.svg=null;graphRuntime.drag=null;graphRuntime.pointers.clear();}
function graphMount(){const svg=$('#network-svg');if(!svg||ui.view!=='relations')return;graphRuntime.svg=svg;const stage=$('#network-stage');const measure=()=>{const box=stage.getBoundingClientRect();const previous={width:graphRuntime.width,height:graphRuntime.height};graphRuntime.width=box.width;graphRuntime.height=box.height;if(graphUI.transform&&previous.width&&previous.height){graphUI.transform.x+=(box.width-previous.width)/2;graphUI.transform.y+=(box.height-previous.height)/2;}if(graphUI.pending){const action=graphUI.pending;graphUI.pending=null;graphViewportAction(action);}else if(!graphUI.transform)graphViewportAction('fit-connected');else graphApplyTransform();};measure();if(typeof ResizeObserver!=='undefined'){graphRuntime.observer=new ResizeObserver(()=>{if(graphRuntime.svg===svg)measure();});graphRuntime.observer.observe(stage);}svg.addEventListener('wheel',event=>{event.preventDefault();const box=svg.getBoundingClientRect();graphZoomAt(Math.exp(-event.deltaY*.0014),event.clientX-box.left,event.clientY-box.top);},{passive:false});svg.addEventListener('pointerdown',networkPointerDown);svg.addEventListener('pointermove',networkPointerMove);svg.addEventListener('pointerup',networkPointerUp);svg.addEventListener('pointercancel',networkPointerUp);svg.addEventListener('keydown',event=>{if(event.target.closest('[data-network-node]')&&['Enter',' '].includes(event.key)){event.preventDefault();networkFocus(event.target.closest('[data-network-node]').dataset.networkNode,true);return;}if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','0'].includes(event.key)){event.preventDefault();if(event.key==='+'||event.key==='=')graphZoomAt(1.2);else if(event.key==='-')graphZoomAt(1/1.2);else if(event.key==='0')graphViewportAction('fit-all');else{const t=graphUI.transform;t.x+=event.key==='ArrowLeft'?50:event.key==='ArrowRight'?-50:0;t.y+=event.key==='ArrowUp'?50:event.key==='ArrowDown'?-50:0;graphApplyTransform();}}});}
function graphApplyTransform(){const t=graphUI.transform;if(!t)return;const viewport=$('#network-viewport');if(viewport){viewport.setAttribute('transform',`translate(${t.x},${t.y}) scale(${t.k})`);viewport.classList.toggle('zoom-far',t.k<.46);viewport.classList.toggle('zoom-medium',t.k<.85);}const zoom=$('#network-zoom');if(zoom)zoom.textContent=Math.round(t.k*100)+'%';}
function graphZoomAt(factor,x=graphRuntime.width/2,y=graphRuntime.height/2){if(!graphUI.transform)return;const t=graphUI.transform,k=Math.max(.06,Math.min(4,t.k*factor)),ratio=k/t.k;t.x=x-(x-t.x)*ratio;t.y=y-(y-t.y)*ratio;t.k=k;graphApplyTransform();}
function graphViewportAction(action){const layout=graphRuntime.layout,graph=graphRuntime.graph;if(!layout)return;if(action==='fit-all'||action==='fit-connected'){const bounds=action==='fit-connected'&&graph.connectedIds.size?layout.connectedBounds:layout.allBounds;graphUI.transform=graphCore().fitTransform(bounds,graphRuntime.width,graphRuntime.height,65);}else if(action==='focus'){const p=layout.positions.get(ui.focus);if(p){const k=Math.max(.9,Math.min(1.4,graphUI.transform?.k||1.1));graphUI.transform={k,x:graphRuntime.width/2-p.x*k,y:graphRuntime.height/2-p.y*k};}}else if(action==='actual'){const current=graphUI.transform?.k||1;graphZoomAt(1/current);return;}graphApplyTransform();}
function pointerPosition(event){const box=graphRuntime.svg.getBoundingClientRect();return {x:event.clientX-box.left,y:event.clientY-box.top};}
function networkPointerDown(event){if(event.button!==0&&event.pointerType==='mouse')return;const svg=graphRuntime.svg,pos=pointerPosition(event);graphRuntime.pointers.set(event.pointerId,pos);svg.setPointerCapture(event.pointerId);if(graphRuntime.pointers.size===2){const [a,b]=[...graphRuntime.pointers.values()];graphRuntime.drag={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),center:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},transform:{...graphUI.transform},moved:true};return;}const node=event.target.closest('[data-network-node]'),edge=event.target.closest('[data-network-pair]');graphRuntime.drag={type:node?'node':edge?'edge':'pan',id:node?.dataset.networkNode||edge?.dataset.networkPair,start:pos,last:pos,position:node?{...graphRuntime.layout.positions.get(node.dataset.networkNode)}:null,transform:{...graphUI.transform},moved:false};svg.classList.add('grabbing');}
function networkPointerMove(event){if(!graphRuntime.pointers.has(event.pointerId)||!graphRuntime.drag)return;const pos=pointerPosition(event);graphRuntime.pointers.set(event.pointerId,pos);const d=graphRuntime.drag;if(d.type==='pinch'&&graphRuntime.pointers.size>=2){const [a,b]=[...graphRuntime.pointers.values()],center={x:(a.x+b.x)/2,y:(a.y+b.y)/2},distance=Math.hypot(a.x-b.x,a.y-b.y),k=Math.max(.06,Math.min(4,d.transform.k*distance/Math.max(1,d.distance)));graphUI.transform={k,x:center.x-(d.center.x-d.transform.x)/d.transform.k*k,y:center.y-(d.center.y-d.transform.y)/d.transform.k*k};graphApplyTransform();return;}const dx=pos.x-d.start.x,dy=pos.y-d.start.y;if(Math.hypot(dx,dy)>4)d.moved=true;if(d.type==='node'&&d.moved){const position={x:d.position.x+dx/graphUI.transform.k,y:d.position.y+dy/graphUI.transform.k,group:d.position.group};graphRuntime.layout.positions.set(d.id,position);graphUI.overrides[d.id]={x:position.x,y:position.y};const node=$(`[data-network-node="${CSS.escape(d.id)}"]`);node?.setAttribute('transform',`translate(${position.x},${position.y})`);for(const e of graphRuntime.visualEdges){if(e.a!==d.id&&e.b!==d.id)continue;const a=graphRuntime.layout.positions.get(e.a),b=graphRuntime.layout.positions.get(e.b),group=$(`g[data-network-pair="${CSS.escape(e.id)}"]`);if(group){for(const line of $$('line',group)){line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',b.x);line.setAttribute('y2',b.y);}$('.network-edge-label',group)?.setAttribute('transform',`translate(${(a.x+b.x)/2},${(a.y+b.y)/2})`);}}}else if(d.type==='pan'){graphUI.transform.x=d.transform.x+dx;graphUI.transform.y=d.transform.y+dy;graphApplyTransform();}}
function networkPointerUp(event){const d=graphRuntime.drag;graphRuntime.pointers.delete(event.pointerId);try{graphRuntime.svg?.releasePointerCapture(event.pointerId);}catch{}if(!graphRuntime.pointers.size){graphRuntime.svg?.classList.remove('grabbing');graphRuntime.drag=null;}if(!d)return;if(d.type==='node'&&!d.moved){networkFocus(d.id,false);}else if(d.type==='edge'&&!d.moved){networkSelectPair(d.id);}if(d.type==='node'&&d.moved){graphRuntime.layout.allBounds=graphCore().boundsOf([...graphRuntime.layout.positions.values()]);graphRuntime.layout.connectedBounds=graphCore().boundsOf([...graphRuntime.graph.connectedIds].map(id=>graphRuntime.layout.positions.get(id)));}if(graphRuntime.pointers.size===1){const remaining=[...graphRuntime.pointers.values()][0];graphRuntime.drag={type:'pan',start:remaining,last:remaining,transform:{...graphUI.transform},moved:true};}}
function networkFocus(id,center=true){const k=getKol(id);if(!k)return;ui.focus=id;ui.edge='';if(!graphRuntime.graph?.nodes.some(n=>n.id===id)){graphUI.people='all';graphUI.showIsolates=true;graphUI.depth='all';toast('已扩大人选范围并显示该UP，作品证据筛选保持不变');}graphUI.details=true;if(center)graphUI.pending='focus';render();}
function networkSelectPair(pair){const visual=graphRuntime.visualEdges.find(e=>e.id===pair);if(!visual)return;ui.edge=(visual.history||visual.proposed).id;graphUI.details=true;render();}
function networkSearch(){const input=$('#network-search'),value=input?.value?.trim();if(!value)return;const id=graphRuntime.graph?.model.resolve(value);if(!id){toast('未找到完全匹配的UP，请从名称建议中选择，或输入UID');return;}networkFocus(id,true);}
document.addEventListener('click',event=>{const control=event.target.closest('[data-network-action]');if(control){const action=control.dataset.networkAction;if(action==='search')networkSearch();else if(action==='zoom-in')graphZoomAt(1.25);else if(action==='zoom-out')graphZoomAt(.8);else if(['fit-all','fit-connected','actual'].includes(action))graphViewportAction(action);else if(action==='locate')networkFocus(ui.focus,true);else if(action==='toggle-details'){graphUI.details=!graphUI.details;render();}else if(action==='clear-edge'){ui.edge='';render();}else if(action==='reset-layout'){graphUI.overrides={};graphUI.pending='fit-connected';render();}else if(action==='reset-filters'){Object.assign(graphUI,{depth:'all',minCount:'1',form:'all',evidence:'all',years:'all',people:'all',showProposed:false,showIsolates:true,includeUnknownDates:false});graphUI.pending='fit-connected';render();}return;}const pair=event.target.closest('button[data-network-pair]');if(pair)networkSelectPair(pair.dataset.networkPair);});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.networkFilter){graphUI[el.dataset.networkFilter]=el.type==='checkbox'?el.checked:el.value;ui.edge='';graphUI.pending=el.dataset.networkFilter==='showProposed'?null:'fit-connected';render();}else if(el.id==='network-search')networkSearch();});
document.addEventListener('keydown',event=>{if(event.target.id==='network-search'&&event.key==='Enter'){event.preventDefault();networkSearch();}});


function field(name,label,value,type='text',extra=''){return `<div class="field ${extra}"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" data-edit="${name}" type="${type}" ${type==='number'?'min="0" step="any"':''} value="${esc(value??'')}"></div>`;}
function textField(name,label,value){return `<div class="field full"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" data-edit="${name}">${esc(value||'')}</textarea></div>`;}
function checks(ids){return `<div class="check-grid">${state.sellingPoints.map(p=>`<label class="check-item"><input type="checkbox" data-edit-sell="${p.id}" ${ids.includes(Number(p.id))?'checked':''}><span>${String(p.id).padStart(2,'0')} · ${esc(shortSell(p.id))}</span></label>`).join('')}</div>`;}
function sourceDetails(sources){return `<details><summary>查看来源与历史信息 (${sources?.length||0})</summary><div class="detail-text">${(sources||[]).map(s=>`<p>${esc(typeof s==='string'?s:[s.file||s.path||s.name,s.sheet?`「${s.sheet}」`:'',s.row?`第${s.row}行`:'',s.note||''].filter(Boolean).join(' · '))}</p>`).join('')||'未记录来源'}</div></details>`;}
function openKol(id){const k=id?getKol(id):{id:'up-'+Date.now(),name:'',category:'待分类',contentType:'',followersWan:null,quoteWan:null,quoteNote:'',quoteUnit:'万元/条（待核）',status:'待询价',supplier:'',homepage:'',selected:false,sellingPoints:[],sources:[],metrics:{recent20Max:null,recent20Avg:null,sampleSize:0}};if(!k)return;modal={kind:'kol',draft:structuredClone(k),isNew:!id,tab:'profile'};openModal();}
function openIdea(id,ids=[]){const i=id?state.ideas.find(i=>i.id===id):{id:'C-'+Date.now().toString().slice(-8),title:'',description:'',type:'内容创意',budgetCategory:state.budgets[0].name,kolIds:ids,allocations:ids.map(id=>({kolId:id,quantity:num(getKol(id)?.quantity)??1,quoteWan:getKol(id)?.quoteWan??null})),sellingPoints:uniq(ids.flatMap(id=>getKol(id)?.sellingPoints||[])),manualBudget:null,status:'草案',archived:false,inBudget:true,images:[],sources:[]};if(!i)return;modal={kind:'idea',draft:structuredClone(i),isNew:!id,memberQ:'',poolChoice:state.planner.ideaIds.includes(i.id)};openModal();}
function openModal(){modalBeforeFocus=document.activeElement;renderModal();document.body.style.overflow='hidden';setTimeout(()=>$('.drawer .close')?.focus(),0);}
function closeModal(){modal=null;$('#modal-root').innerHTML='';document.body.style.overflow='';modalBeforeFocus?.focus?.();}
function renderModal(){if(!modal)return;const d=modal.draft;let title,desc,body,footer;if(modal.kind==='kol'){title=modal.isNew?'新增UP资料':d.name;desc='基础信息、推荐卖点与作品证据';body=kolEditor();footer=`<label class="toggle-line"><input type="checkbox" data-edit="selected" ${d.selected?'checked':''}>纳入本轮人选</label><div class="actions"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-modal">保存资料</button></div>`;}else if(modal.kind==='idea'){title=modal.isNew?'新建创意':d.title;desc='将卖点、人选与预算组合成一项内容';body=ideaEditor();footer=`<label class="toggle-line"><input type="checkbox" data-edit="inBudget" ${d.inBudget?'checked':''}>纳入预算看板</label><div class="actions">${!modal.isNew?`<button class="btn ${d.archived?'':'danger'}" data-action="archive-idea">${d.archived?'恢复创意':'归档创意'}</button>`:''}<button class="btn primary" data-action="save-modal">保存创意</button></div>`;}else if(modal.kind==='budgets'){title='调整计划预算';desc='单位：万元 · 调整额度不会修改创意金额';body=`<div class="form-section"><div class="form-grid">${d.map((b,i)=>field(`budget-${i}`,b.name,b.amount,'number')).join('')}</div><p class="bottom-note">这是本系统的策划预算额度，不表示采购审批或实际付款。</p></div>`;footer=`<span class="caption">原始图示总额 4,150万元</span><div class="actions"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-modal">保存预算</button></div>`;}else if(modal.kind==='edge'){title='补充真实合作记录';desc='请记录具体作品与链接，避免将建议组合计入合作历史';body=`<div class="form-section"><div class="form-grid"><div class="field"><label>UP A</label><select data-edit="a">${options(state.kols.map(k=>({id:k.id,title:k.name})),d.a,'选择UP')}</select></div><div class="field"><label>UP B</label><select data-edit="b">${options(state.kols.map(k=>({id:k.id,title:k.name})),d.b,'选择UP')}</select></div>${field('title','合作作品标题',d.title,'text','full')}${field('url','作品链接（必填）',d.url,'url','full')}${field('date','发布日期',d.date,'date')}${field('platform','平台',d.platform)}<div class="field"><label>合作形式</label><select data-edit="type">${Object.entries(graphCore().FORMS).map(([v,l])=>`<option value="${v}" ${d.type===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>证据来源（默认待核）</label><select data-edit="evidenceLevel">${Object.entries(graphCore().LEVELS).map(([v,l])=>`<option value="${v}" ${d.evidenceLevel===v?'selected':''}>${l}</option>`).join('')}</select></div>${textField('creative','合作做了什么 / 节目分工',d.creative)}</div></div><div class="form-section"><h3>这对组合可表达的卖点（建议）</h3>${checks(d.sellingPoints||[])}</div>`;footer=`<span class="caption">人工补录，保留证据链接</span><div class="actions"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="save-modal">保存记录</button></div>`;}$('#modal-root').innerHTML=`<div class="drawer-backdrop" data-backdrop><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><h2 id="dialog-title">${esc(title)}</h2><p class="caption">${esc(desc)}</p></div><button class="close" data-action="close-modal" aria-label="关闭">×</button></header><div class="drawer-body">${body}</div><footer class="drawer-footer">${footer}</footer></section></div>`;}
function kolEditor(){const k=modal.draft,m=k.metrics||{},videos=k.recentVideos||[],games=k.gameEvidence?.length?k.gameEvidence:(k.games||[]);return `<div class="detail-hero">${avatar(k,'lg')}<div><h2>${esc(k.name||'新UP')}</h2><div class="tags">${pill(k.category)}${pill(k.status||'待核实',k.selected?'blue':'')}${k.selected?pill('本轮已选','green'):''}</div><div class="caption" style="margin-top:8px">${external(k.homepage,'查看主页')}</div></div><div class="detail-price"><span class="caption">参考报价 · 万元</span><div><b>${fmt(k.quoteWan)}</b></div><small class="muted">${esc(k.quoteUnit||'合作形式与单位待核')}</small></div></div><div class="tabs">${[['profile','基础资料'],['match','卖点与推荐'],['evidence','作品与合作证据']].map(([v,t])=>`<button class="tab ${modal.tab===v?'active':''}" data-modal-tab="${v}">${t}</button>`).join('')}</div>${modal.tab==='profile'?`<div class="form-section"><h3>基础资料</h3><div class="form-grid">${field('name','UP名称 *',k.name)}${field('uid','平台UID',k.uid)}${field('category','主分区',k.category)}${field('contentType','内容类型',k.contentType)}${field('followersWan','粉丝数（万）',k.followersWan,'number')}${field('homepage','主页链接',k.homepage,'url')}${field('avatar','头像URL',k.avatar||k.avatarUrl,'url','full')}</div><p class="caption">${esc(avatarSourceNote(k)||'头像来源日期待补')}${/^https?:/.test(k.avatarSource||'')?` · ${external(k.avatarSource,'头像来源')}`:''}</p></div><div class="form-section"><h3>报价与推进</h3><div class="form-grid">${field('quoteWan','参考单价（万元）',k.quoteWan,'number')}${field('quoteUnit','报价单位 / 合作形式',k.quoteUnit)}${field('status','推进状态',k.status)}${field('supplier','供应商 / 渠道',k.supplier)}${field('schedule','档期与确认',k.schedule||k.availability,'text','full')}${textField('quoteNote','报价依据与权益范围',k.quoteNote)}${textField('latestFeedback','最新反馈',k.latestFeedback||k.feedback||'')}</div></div>${k.quoteOptions?.length?`<div class="form-section"><h3>不同形式的报价记录</h3><div class="table-wrap"><table><thead><tr><th>金额 / 形式 / 来源</th></tr></thead><tbody>${k.quoteOptions.slice(0,20).map(q=>`<tr><td>${esc(typeof q==='string'?q: Object.entries(q).map(([key,v])=>`${({quoteWan:'报价(万)',amount:'金额',form:'形式',unit:'单位',note:'说明',source:'来源',file:'文件',sheet:'页',row:'行',priceWan:'报价(万)'})[key]||key}：${plain(v)}`).join(' · '))}</td></tr>`).join('')}</tbody></table></div></div>`:''}${sourceDetails(k.sources)}${k.conflicts?.length?`<details><summary>版本差异 / 待核项 (${k.conflicts.length})</summary><div class="detail-text">${k.conflicts.map(c=>`<p>${esc(plain(c))}</p>`).join('')}</div></details>`:''}`:modal.tab==='match'?`<div class="form-section"><h3>推荐卖点 <span class="pill blue">策划建议，可调整</span></h3>${checks(k.sellingPoints||[])}<div class="section-gap">${textField('matchReason','为什么是他 / 内容切入建议',k.matchReason||'')}</div></div><div class="form-section"><h3>人群与表达能力</h3><div class="form-grid">${textField('audience','主要覆盖人群',plain(k.audience||k.audienceTags||''))}${textField('strengths','内容能力 / 代表特征',plain(k.strengths||''))}</div></div><div class="note">标签用于解释匹配逻辑，不代表已验证效果。跨圈人选需结合真实作品、游戏合作经验与节目分工判断。</div>`:`${KOLPerformance.detail(k)}${historicalEvidence(k)}<div class="form-section"><h3>研究备注与补充证据</h3>${textField('researchNotes','可记录作品链接、合作对象与核查结论',k.researchNotes||'')}${sourceDetails(k.researchSources||k.sources)}</div>`}`;}
function ideaEditor(){const i=modal.draft,cost=costing(i);return `<label class="toggle-line pool-idea-choice"><input type="checkbox" data-pool-choice ${modal.poolChoice?'checked':''} ${window.KOLPersistence?.readonly?'disabled':''}> 加入 KOL + 创意中选池</label><div class="form-section"><h3>创意内容</h3><div class="form-grid">${field('title','创意标题 *',i.title,'text','full')}${textField('description','一句话简介 / 具体做什么',i.description)}${field('type','创意类型',i.type)}<div class="field"><label>归属预算单</label><select data-edit="budgetCategory">${options(state.budgets.map(b=>b.name),i.budgetCategory,'选择预算分类')}</select></div>${field('status','推进状态',i.status)}${field('node','传播节点',i.node||i.timing||'')}${textField('execution','内容结构、节目分工与待确认点',i.execution||i.notes||'')}</div></div><div class="form-section"><h3>这个创意表达什么卖点</h3>${checks(i.sellingPoints||[])}${textField('sellingReason','观众应该感受到什么',i.sellingReason||'')}</div><div class="form-section"><h3>参与UP <button class="btn small" data-action="add-selected">${icon('plus')}加入本轮已选UP</button></h3><div id="chosen-members">${chosenMembers()}</div><div class="search">${icon('search')}<input id="member-search" data-member-query placeholder="从UP库搜索并添加…" value="${esc(modal.memberQ||'')}"></div><div class="member-picker" id="member-picker">${memberPicker()}</div><p class="caption" style="margin-top:8px">原表匹配人选可能包含互斥备选；纳入预算前，请按实际阵容删选。添加多人可用于联机或联合视频。</p></div><div class="form-section"><h3>预算测算 <span class="pill">单位：万元</span></h3><div id="member-prices">${memberPrices()}</div><div class="form-grid section-gap">${field('manualBudget','手动总价（留空使用报价合计）',i.manualBudget,'number')}${field('budgetNote','议价 / 打包说明',i.budgetNote||'')}</div><div id="idea-calc">${calcHtml()}</div><p class="bottom-note">参考单价与数量可逐人修改；单价留空沿用UP资料报价。直播按小时/场、视频按条分别核对，不能把不同单位默认当同一种合作。</p></div><div class="form-section"><h3>创意示意图 <span class="caption">最多3张 · 点击空位上传</span></h3><div class="uploads">${[0,1,2].map(n=>{const url=safeUrl(i.images[n]?.url||i.images[n]);return `<div class="image-slot">${url?`<img src="${esc(url)}" alt="创意示意图${n+1}"><button class="remove-image" data-remove-image="${n}" aria-label="移除示意图${n+1}">×</button>`:`<span>${icon('image')}<br>添加示意图 ${n+1}</span><label><input class="file-input" type="file" accept="image/png,image/jpeg,image/webp" data-upload-image="${n}" aria-label="上传示意图${n+1}"></label>`}</div>`;}).join('')}</div></div>${sourceDetails(i.sources)}${i.archived?'<div class="note warn">这是一条历史归档创意，不计入预算和活跃创意覆盖。保留原始取舍理由，恢复后再评估。</div>':''}`;}
function chosenMembers(){return `<div class="members-chosen">${modal.draft.kolIds.map(id=>{const k=getKol(id);return k?`<span class="member-chip">${avatar(k,'sm')}${esc(k.name)}<button data-remove-member="${esc(id)}" aria-label="移除${esc(k.name)}">×</button></span>`:'';}).join('')||'<p class="caption">还未匹配UP</p>'}</div>`;}
function memberPicker(){const q=(modal.memberQ||'').toLowerCase();return state.kols.filter(k=>!q||[k.name,k.category].join(' ').toLowerCase().includes(q)).sort((a,b)=>Number(b.selected)-Number(a.selected)).slice(0,50).map(k=>`<label class="member-item"><input type="checkbox" data-add-member="${esc(k.id)}" ${modal.draft.kolIds.includes(k.id)?'checked':''}>${avatar(k,'sm')}<div><b>${esc(k.name)}</b><div class="caption">${esc(k.category)}</div></div><span class="price">${amount(k.quoteWan)}</span></label>`).join('')||'<p class="empty">没有匹配的UP</p>';}
function memberPrices(){return `<div class="member-row caption"><span>参与人 / 原报价形式</span><span>数量</span><span>单价（万）</span><span>小计</span></div>${allocations(modal.draft).map(a=>{const k=getKol(a.kolId);return `<div class="member-row"><div class="person">${avatar(k,'sm')}<div>${esc(k?.name||a.kolId)}<div class="caption">${esc(k?.quoteUnit||'单位待核')}</div></div></div><input type="number" min="0" step="any" data-allocation="quantity" data-person="${esc(a.kolId)}" value="${a.quantity}" aria-label="${esc(k?.name)}数量"><input type="number" min="0" step="any" data-allocation="quoteWan" data-person="${esc(a.kolId)}" value="${a.quoteWan??''}" placeholder="待询价" aria-label="${esc(k?.name)}单价"><span class="number" id="subtotal-${esc(a.kolId)}">${a.quoteWan==null?'待询价':fmt(a.quoteWan*a.quantity)}</span></div>`;}).join('')}`;}
function calcHtml(){const c=costing(modal.draft);return `<div class="budget-calc"><div>${c.manual?'手动总价':'已知报价合计'}<p class="caption">自动合计 ${fmt(c.auto)}万${c.missing?` · ${c.missing}位报价待补`:''}</p></div><div><b>${fmt(c.total)}</b> 万</div></div>`;}
function updateMemberSections(){if(!modal||modal.kind!=='idea')return;$('#chosen-members').innerHTML=chosenMembers();$('#member-picker').innerHTML=memberPicker();$('#member-prices').innerHTML=memberPrices();$('#idea-calc').innerHTML=calcHtml();}
function addMember(id,yes){const i=modal.draft;i.kolIds=yes?uniq([...i.kolIds,id]):i.kolIds.filter(x=>x!==id);i.allocations=i.allocations||[];if(yes&&!i.allocations.some(a=>a.kolId===id))i.allocations.push({kolId:id,quantity:1,quoteWan:getKol(id)?.quoteWan??null});if(!yes)i.allocations=i.allocations.filter(a=>a.kolId!==id);updateMemberSections();}
async function saveModal(){const m=modal;if(!m)return;const d=structuredClone(m.draft);if(m.kind==='kol'){if(!d.name?.trim()){toast('请填写UP名称',true);return;}if(d.homepage&&!/^https?:\/\//i.test(d.homepage)){toast('主页请填写完整的 http 或 https 链接',true);return;}if([d.followersWan,d.quoteWan,d.quantity].some(v=>v!=null&&(num(v)==null||num(v)<0))){toast('粉丝数、报价与数量须为非负数字',true);return;}d.name=d.name.trim();d.updatedAt=new Date().toISOString();d.editedByUser=true;const ok=await transact(()=>{const n=state.kols.findIndex(k=>k.id===d.id);if(n>=0)state.kols[n]=d;else state.kols.push(d);},'UP资料已保存');if(ok)closeModal();}else if(m.kind==='idea'){if(!d.title?.trim()){toast('请给创意起一个标题',true);return;}if(d.inBudget&&!d.budgetCategory){toast('纳入预算前请选择预算分类',true);return;}if(d.manualBudget!=null&&(num(d.manualBudget)==null||num(d.manualBudget)<0)){toast('手动总价须为非负数字',true);return;}if(d.allocations.some(a=>(num(a.quantity)??-1)<0||(a.quoteWan!=null&&num(a.quoteWan)<0))){toast('数量与报价不能为负数',true);return;}d.title=d.title.trim();d.updatedAt=new Date().toISOString();const ok=await transact(()=>{const n=state.ideas.findIndex(i=>i.id===d.id);if(n>=0)state.ideas[n]=d;else state.ideas.unshift(d);const set=new Set(state.planner.ideaIds);if(m.poolChoice)set.add(d.id);else set.delete(d.id);state.planner.ideaIds=[...set];},'创意已保存，预算与覆盖已更新');if(ok)closeModal();}else if(m.kind==='budgets'){if(d.some(b=>num(b.amount)==null||Number(b.amount)<0)){toast('预算额度须填写非负数字',true);return;}const ok=await transact(()=>state.budgets=d,'预算额度已更新');if(ok)closeModal();}else if(m.kind==='edge'){if(!d.a||!d.b||d.a===d.b){toast('请选择两位不同的UP',true);return;}if(!d.title?.trim()||!/^https?:\/\//i.test(d.url||'')){toast('请补充合作作品标题和有效链接',true);return;}const exists=[...(state.manualEdges||[]),...(research.edges||[])].some(e=>e.url===d.url&&[e.a,e.b].sort().join('|')===[d.a,d.b].sort().join('|'));if(exists){toast('这条合作记录已存在，无需重复添加',true);return;}d.id='record-'+Date.now();d.kind='history';d.status='人工补录 · 链接待复核';d.recordedAt=new Date().toISOString();d.sourceCheckedAt=graphCore().todayShanghai();d.workId=graphCore().workKey(d);d.contentSummary=d.creative;const ok=await transact(()=>state.manualEdges.push(d),'合作记录已保存');if(ok){ui.focus=d.a;ui.view='relations';closeModal();render();}}}
function exportData(){const payload={...KOLPerformance.forExport(state),exportedAt:new Date().toISOString(),app:'ANANTA KOL LAB',schemaVersion:2};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`ANANTA_KOL备份_${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('备份已导出');}
function validateImport(data){if(data&&data.brainFactory===undefined&&state?.brainFactory)data.brainFactory=structuredClone(state.brainFactory);if(data&&data.planner===undefined&&state?.planner)data.planner=structuredClone(state.planner);if(!data||!Array.isArray(data.kols)||!Array.isArray(data.ideas)||!Array.isArray(data.budgets))throw Error('备份必须包含 kols、ideas、budgets 数组');if(data.kols.length>20000||data.ideas.length>10000)throw Error('数据量超出本版导入上限');if(data.kols.some(k=>!k.id||typeof k.name!=='string'))throw Error('UP记录缺少id或名称');if(uniq(data.kols.map(k=>String(k.id))).length!==data.kols.length)throw Error('UP ID重复');if(uniq(data.ideas.map(i=>String(i.id))).length!==data.ideas.length)throw Error('创意 ID重复');const ids=new Set(data.kols.map(k=>String(k.id)));if(data.ideas.some(i=>!i.id||typeof i.title!=='string'||!Array.isArray(i.kolIds)||i.kolIds.some(id=>!ids.has(String(id)))))throw Error('创意人选引用或字段格式无效');if(data.budgets.some(b=>typeof b.name!=='string'||num(b.amount)==null||Number(b.amount)<0))throw Error('预算数据无效');if(data.kols.some(k=>[k.followersWan,k.quoteWan,k.quantity].some(v=>v!=null&&(num(v)==null||num(v)<0))))throw Error('UP金额、粉丝数或数量无效');if(data.ideas.some(i=>(i.manualBudget!=null&&(num(i.manualBudget)==null||num(i.manualBudget)<0))||uniq(i.kolIds.map(String)).length!==i.kolIds.length))throw Error('创意总价无效或人选重复');if(data.ideas.some(i=>(i.allocations||[]).some(a=>!i.kolIds.map(String).includes(String(a.kolId))||(a.quantity!=null&&(num(a.quantity)==null||num(a.quantity)<0))||(a.quoteWan!=null&&(num(a.quoteWan)==null||num(a.quoteWan)<0)))))throw Error('创意计价明细无效');if(data.ideas.some(i=>i.inBudget&&!i.archived&&!data.budgets.some(b=>b.name===i.budgetCategory)))throw Error('已纳入创意缺少有效预算分类');return normalize(data);}
async function readImage(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('请选择 PNG、JPG 或 WebP 图片');if(file.size>20*1024*1024)throw Error('单张图片请小于20MB');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas'),ratio=Math.min(1,1400/Math.max(img.width,img.height));canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.8);}finally{URL.revokeObjectURL(url);}}
document.addEventListener('click',async event=>{const el=event.target.closest('button,[data-kol],[data-idea],[data-edge],[data-graph-focus],[data-budget-filter],[data-backdrop]');if(event.target.closest('[data-select-kol]'))return;if(!el)return;if(el.hasAttribute('data-backdrop')){if(event.target===el)closeModal();return;}if(el.dataset.nav){ui.view=el.dataset.nav;render();window.scrollTo(0,0);return;}if(el.dataset.page){ui.page=Number(el.dataset.page);render();window.scrollTo(0,220);return;}if(el.dataset.kol){openKol(el.dataset.kol);return;}if(el.dataset.idea){openIdea(el.dataset.idea);return;}if(el.dataset.budgetFilter){ui.ideaBudget=ui.ideaBudget===el.dataset.budgetFilter?'':el.dataset.budgetFilter;render();return;}if(el.dataset.budgetView){ui.ideaBudget=el.dataset.budgetView;ui.ideaStatus='budget';ui.view='ideas';render();return;}if(el.dataset.ideaStatus){ui.ideaStatus=el.dataset.ideaStatus;render();return;}if(el.dataset.sellKols){ui.view='kols';ui.sell=el.dataset.sellKols;ui.page=1;render();return;}if(el.dataset.sellIdeas){ui.view='ideas';ui.ideaSell=el.dataset.sellIdeas;render();return;}if(el.dataset.edge){ui.edge=el.dataset.edge;render();return;}if(el.dataset.graphFocus){ui.focus=el.dataset.graphFocus;ui.edge='';render();return;}if(el.dataset.modalTab){modal.tab=el.dataset.modalTab;renderModal();return;}if(el.dataset.removeMember){addMember(el.dataset.removeMember,false);return;}if(el.dataset.removeImage!==undefined){modal.draft.images[Number(el.dataset.removeImage)]='';renderModal();return;}const action=el.dataset.action;switch(action){case'close-modal':closeModal();break;case'new-kol':openKol();break;case'new-idea':openIdea();break;case'idea-from-selected':if(!selectedKols().length){toast('先选择至少一位UP');break;}openIdea(null,selectedKols().map(k=>k.id));break;case'add-selected':selectedKols().forEach(k=>addMember(k.id,true));break;case'save-modal':await saveModal();break;case'archive-idea':modal.draft.archived=!modal.draft.archived;if(modal.draft.archived)modal.draft.inBudget=false;await saveModal();break;case'edit-budgets':modal={kind:'budgets',draft:structuredClone(state.budgets)};openModal();break;case'new-edge':modal={kind:'edge',draft:{a:ui.focus,b:'',title:'',url:'',date:'',platform:'B站',creative:'',type:'collaboration',evidenceLevel:'manual',sellingPoints:[]}};openModal();break;case'export':exportData();break;case'import':$('#import-file').click();break;case'retry':location.reload();break;}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.filter){ui[el.dataset.filter]=el.value;ui.page=1;render();}if(el.hasAttribute('data-member-query')){modal.memberQ=el.value;$('#member-picker').innerHTML=memberPicker();}if(el.dataset.edit&&modal){let value=el.type==='checkbox'?el.checked:el.type==='number'?num(el.value):el.value;if(modal.kind==='budgets'){const n=Number(el.dataset.edit.split('-')[1]);modal.draft[n].amount=value;}else{modal.draft[el.dataset.edit]=value;if(el.dataset.edit==='avatar'){modal.draft.avatarUserOwned=true;modal.draft.avatarOrigin='user';modal.draft.avatarAssetVerified=false;modal.draft.avatarSource='用户手动填写';modal.draft.avatarCheckedAt=null;modal.draft.historicalAvatar=false;modal.draft.sourceSnapshotDate=null;modal.draft.currentAvatarVerified=null;}if(el.dataset.edit==='manualBudget'&&$('#idea-calc'))$('#idea-calc').innerHTML=calcHtml();}}if(el.dataset.allocation&&modal){const id=el.dataset.person;let a=modal.draft.allocations.find(a=>a.kolId===id);if(!a){a={kolId:id,quantity:1,quoteWan:getKol(id)?.quoteWan??null};modal.draft.allocations.push(a);}a[el.dataset.allocation]=num(el.value);const sub=document.getElementById('subtotal-'+id);if(sub)sub.textContent=(num(a.quoteWan)??num(getKol(id)?.quoteWan))==null?'待询价':fmt((num(a.quoteWan)??num(getKol(id)?.quoteWan))*(a.quantity??0));$('#idea-calc').innerHTML=calcHtml();}});
document.addEventListener('change',async event=>{const el=event.target;if(el.hasAttribute('data-pool-choice')&&modal?.kind==='idea'){modal.poolChoice=el.checked;return;}if(el.dataset.selectKol){const id=el.dataset.selectKol;const checked=el.checked;await transact(()=>{const k=getKol(id);if(k)k.selected=checked;},checked?'已加入本轮人选':'已移出本轮人选');}if(el.dataset.editSell&&modal){const n=Number(el.dataset.editSell);modal.draft.sellingPoints=el.checked?uniq([...(modal.draft.sellingPoints||[]),n]):(modal.draft.sellingPoints||[]).filter(x=>x!==n);}if(el.dataset.addMember&&modal)addMember(el.dataset.addMember,el.checked);if(el.id==='graph-person-search'){const k=state.kols.find(k=>k.name===el.value);if(k){ui.focus=k.id;ui.edge='';render();}}if(el.dataset.uploadImage!==undefined&&el.files?.[0]){try{const img=await readImage(el.files[0]);modal.draft.images[Number(el.dataset.uploadImage)]=img;renderModal();toast('图片已加入草稿，保存创意后生效');}catch(e){toast(e.message,true);}}if(el.id==='import-file'&&el.files?.[0]){try{const file=el.files[0];if(file.size>40*1024*1024)throw Error('备份文件请小于40MB');const data=validateImport(JSON.parse(await file.text()));if(confirm(`将用备份中的 ${data.kols.length} 位UP、${data.ideas.length} 项创意替换当前资料。是否继续？`)){await transact(()=>state=data,'备份已导入');}}catch(e){toast('导入失败：'+e.message,true);}el.value='';}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal){closeModal();return;}if(modal&&event.key==='Tab'){const nodes=$$('button,input,select,textarea,a[href],[tabindex="0"]',$('.drawer')).filter(el=>!el.disabled&&el.offsetParent!==null);if(nodes.length){const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-kol],[data-idea],[data-edge],[data-graph-focus]')){event.preventDefault();event.target.click();}});
document.addEventListener('error',event=>{const target=event.target;if(target?.dataset?.avatarSrc){avatarLoadFailures.add(target.dataset.avatarSrc);target.style.display='none';target.parentElement?.setAttribute('title','头像加载失败，可在资料中补充');if(String(target.tagName).toLowerCase()==='image'){const parent=target.parentElement;const k=getKol(target.dataset.avatarId);if(parent&&k&&!parent.querySelector('.network-initials')){const text=document.createElementNS('http://www.w3.org/2000/svg','text');text.setAttribute('class','network-initials');text.setAttribute('text-anchor','middle');text.setAttribute('y','5');text.textContent=k.name.slice(0,2);parent.appendChild(text);}}updateAvatarCounters();}else if(target.tagName==='IMG'){target.style.display='none';target.parentElement?.setAttribute('title','图片加载失败，可在详情补充');}},true);
document.addEventListener('load',event=>{const target=event.target;if(target?.dataset?.avatarSrc){avatarLoaded.add(target.dataset.avatarSrc);avatarLoadFailures.delete(target.dataset.avatarSrc);updateAvatarCounters();}},true);
async function boot(){try{await Promise.all([KOLPlan.loadDefaults(),KOLPerformance.load()]);if(!window.KOLPersistence&&location.protocol!=='file:')throw Error('保存服务没有载入，请刷新工作台。');if(!window.KOLGraphCore)await import('./graph-core.js');const response=await fetch('data.json');if(!response.ok)throw Error('原始资料未能载入');seed=await response.json();try{const res=await fetch('research.json');if(res.ok)research=await res.json();}catch{}try{const avatarsResponse=await fetch('avatars.json',{cache:'no-store'});if(avatarsResponse.ok)avatarManifest=await avatarsResponse.json();}catch{}let saved;if(window.KOLPersistence){try{saved=await window.KOLPersistence.load();}catch(e){blocked=true;throw Error('本机资料服务读取失败。为保护已有修改，当前不以初始数据覆盖。请刷新重试：'+e.message);}}else{try{const raw=localStorage.getItem(storageKey);saved=raw?JSON.parse(raw):null;}catch(e){throw Error('本机备份读取失败，请先保留浏览器数据并联系维护者。');}}state=normalize(saved||seed);mergeResearch();mergeAvatarManifest();render();window.KOLApp={getState:()=>KOLPerformance.forExport(state),replaceState:async s=>{const next=validateImport(s);return transact(()=>state=next,'数据已更新');},subscribe:fn=>{listeners.push(fn);return()=>listeners=listeners.filter(x=>x!==fn);},flush:()=>persist(),getResearch:()=>research,getAvatarStats:()=>avatarStats(),reload:()=>location.reload()};}catch(e){$('#app').innerHTML=`<div class="boot"><div class="brand-mark" style="background:#142c42">A</div><h2>资料暂未成功载入</h2><p style="max-width:550px">${esc(e.message)}</p><button class="btn primary" data-action="retry">重新加载</button></div>`;console.error(e);}}
function combinationReason(e){if(!e.sellingPoints.length)return '';const hints={2:'可以尝试有明确分工的朋友挑战，观察协作、互相接梗与临场反应。',4:'可用不同职业身份与角色性格的反差分配节目任务。',12:'可尝试动作模仿或接力内容，让不同表演风格形成反差。',13:'可通过角色关系、日常故事或音乐叙事表达陪伴感。',7:'可先验证竞速、追逐等可用玩法，再设计搭档挑战。',10:'可围绕NPC与城市互动安排共同探索和反应内容。'};return `<div class="relation-record"><strong>组合内容建议</strong><p>${esc(e.sellingPoints.map(id=>hints[id]).filter(Boolean).slice(0,2).join(' ')||'围绕双方擅长的内容形式分配角色，先小规模试玩验证协作，再确定节目结构。')}</p><span class="caption">建议依据公开共创形式与卖点匹配，不是已确认方案或节目效果保证。</span></div>`;}
function historicalEvidence(k){const m=k.metrics||{},records=k.referenceVideos||[];return `<div class="form-section"><h3>源表表现参考 <span class="pill amber">非近期20条</span></h3><div class="metric-grid" style="grid-template-columns:1fr 1fr;margin-bottom:0">${metric('历史5条均播',fmt(m.historical5AvgWan),'按原表快照，不代替近期20条','file','万')}${metric('供应商预估播放',fmt(m.estimatedViewsWan),'预估值，非保量或实际效果','file','万')}</div></div>${records.length?`<div class="form-section"><h3>已有作品案例 <span class="pill">历史参考，非最近20条</span></h3><div class="video-list">${records.map(v=>`<div class="video-item"><div class="video-info"><h4>${external(v.url,v.title||'历史作品')}</h4><div class="video-meta"><span>${esc(v.publishedAt||v.date||'日期待核')}</span><span>播放 ${fmt(v.views)}</span></div><p class="caption">${esc(v.game||'')} · ${esc(v.commercialStatus||v.scope||'合作性质待核')}</p><p class="caption">历史采样：${esc(v.checkedAt||v.asOf||'日期待核')} · ${esc(v.scope||'非近20条样本')}</p></div></div>`).join('')}</div></div>`:''}`;}
boot();
